// Construye la solicitud REST a Qdrant según la operación del puerto vector
const r = $json;
const s = r.settings || {};
const inp = r.input || {};
const base = (s.url || '').replace(/\/$/, '');
const fail = (code, message) => ({ json: { skip: true, status: 'PERMANENT_ERROR', error: { code, message } } });
if (!base) return fail('VALIDATION', 'settings.url del puerto vector no está configurado');
const collection = (s.collections || {})[inp.collection_key];
if (!collection) return fail('VALIDATION', 'collection_key desconocida: ' + inp.collection_key + ' (use una de settings.collections)');
const c = encodeURIComponent(collection);
let method, path, body = null;
switch (r.operation) {
  case 'ensure_collection':
    method = 'PUT'; path = '/collections/' + c;
    body = { vectors: { size: inp.vector_size || s.vector_size, distance: inp.distance || 'Cosine' } };
    break;
  case 'create_payload_index':
    method = 'PUT'; path = '/collections/' + c + '/index?wait=true';
    body = { field_name: inp.field_name, field_schema: inp.field_schema || 'keyword' };
    break;
  case 'upsert':
    method = 'PUT'; path = '/collections/' + c + '/points?wait=true';
    body = { points: inp.points || [] };
    break;
  case 'search':
    method = 'POST'; path = '/collections/' + c + '/points/query';
    body = { query: inp.vector, limit: inp.limit || 5, with_payload: true };
    if (inp.filter) body.filter = inp.filter;
    if (inp.score_threshold !== undefined && inp.score_threshold !== null) body.score_threshold = inp.score_threshold;
    break;
  case 'delete':
    method = 'POST'; path = '/collections/' + c + '/points/delete?wait=true';
    body = inp.ids ? { points: inp.ids } : { filter: inp.filter };
    if (!inp.ids && !inp.filter) return fail('VALIDATION', 'delete requiere ids o filter');
    break;
  case 'scroll':
    method = 'POST'; path = '/collections/' + c + '/points/scroll';
    body = { limit: Math.min(inp.limit || 100, 1000), with_payload: true, with_vector: inp.with_vector === true };
    if (inp.offset !== undefined && inp.offset !== null) body.offset = inp.offset;
    if (inp.filter) body.filter = inp.filter;
    break;
  case 'count':
    method = 'POST'; path = '/collections/' + c + '/points/count';
    body = { exact: true };
    if (inp.filter) body.filter = inp.filter;
    break;
  default:
    return { json: { skip: true, status: 'NOT_SUPPORTED', error: { code: 'OPERATION_NOT_SUPPORTED', message: 'vector.' + r.operation } } };
}
return { json: { skip: false, method, url: base + path, body, collection, timeout_ms: s.timeout_ms || 5000 } };

// Normaliza la respuesta de Qdrant al contrato del puerto vector
const req = $('Solicitud del puerto').item.json;
const built = $('Construir solicitud Qdrant').item.json;
const res = $json;
const code = res.statusCode;
const body = res.body || {};
const op = req.operation;
if (code >= 200 && code < 300) {
  let data;
  if (op === 'search') {
    const points = body.result?.points || body.result || [];
    data = { collection: built.collection, hits: points.map(p => ({ id: p.id, score: p.score, payload: p.payload || {} })) };
  } else if (op === 'scroll') {
    const points = body.result?.points || [];
    data = { collection: built.collection, points: points.map(p => ({ id: p.id, payload: p.payload || {}, vector: p.vector ?? null })), next_offset: body.result?.next_page_offset ?? null };
  } else if (op === 'count') {
    data = { collection: built.collection, count: body.result?.count ?? 0 };
  } else {
    data = { collection: built.collection, result: body.result ?? true };
  }
  return { json: { status: 'OK', data, error: null } };
}
const text = JSON.stringify(body);
if (op === 'ensure_collection' && (code === 409 || /already exists/i.test(text))) {
  return { json: { status: 'OK', data: { collection: built.collection, result: 'already_exists' }, error: null } };
}
if (code === 404) return { json: { status: 'NOT_FOUND', data: null, error: { code: 'COLLECTION_NOT_FOUND', message: text, http_status: code } } };
const retry = code === 408 || code === 429 || code >= 500;
return { json: { status: retry ? 'RETRYABLE_ERROR' : 'PERMANENT_ERROR', data: null, error: { code: 'HTTP_' + code, message: body.status?.error || text, http_status: code } } };

// Timeout o error de red en una operación NO sensible: reintentable
const msg = $json.error?.message ?? String($json.error ?? 'error de red');
return { json: { status: 'RETRYABLE_ERROR', data: null, error: { code: /timeout/i.test(msg) ? 'TIMEOUT' : 'NETWORK_ERROR', message: msg } } };

